INSERT INTO vulnerabilities (id, cve_id, title, description, severity, cvss_score, source, published_at, is_active, created_by, created_at, updated_at) VALUES
  ('ff599d0f-f3bc-542b-91d7-2784eb0ae4e5', 'CVE-2021-44228', 'Apache Log4j2 JNDI remote code execution (Log4Shell)', 'JNDI features in Log4j2 2.0-beta9 to 2.14.1 do not protect against attacker-controlled LDAP and other JNDI endpoints, allowing unauthenticated remote code execution via crafted log messages.', 'CRITICAL', 10.0, 'CISA KEV', '2021-12-10 00:00:00+00', TRUE, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-01 11:00:00+00', '2026-06-01 11:00:00+00'),
  ('3ad38e78-ade2-5494-a42e-22c6030b7e26', 'CVE-2021-45046', 'Apache Log4j2 incomplete fix for Log4Shell in non-default configurations', 'The fix for CVE-2021-44228 was incomplete in certain non-default Pattern Layout configurations, allowing information leak and remote code execution in some environments.', 'CRITICAL', 9.0, 'CISA KEV', '2021-12-14 00:00:00+00', TRUE, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-01 22:00:00+00', '2026-06-01 22:00:00+00'),
  ('d55939f8-f088-5f79-9eda-4ff1de56757d', 'CVE-2022-22965', 'Spring Framework RCE via data binding on JDK 9+ (Spring4Shell)', 'A Spring MVC or WebFlux application running on JDK 9+ may be vulnerable to remote code execution through data binding when deployed as a WAR on Tomcat.', 'CRITICAL', 9.8, 'CISA KEV', '2022-04-01 00:00:00+00', TRUE, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-02 08:00:00+00', '2026-06-02 08:00:00+00'),
  ('17e7d8b2-451f-57c6-8851-2e8835a62bb7', 'CVE-2022-22963', 'Spring Cloud Function SpEL expression injection', 'In Spring Cloud Function 3.1.6, 3.2.2 and older, a crafted spring.cloud.function.routing-expression header allows remote code execution.', 'CRITICAL', 9.8, 'Tenable', '2022-04-01 00:00:00+00', TRUE, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-02 22:00:00+00', '2026-06-02 22:00:00+00'),
  ('4c8751c5-bdab-5059-8265-6c7da1122295', 'CVE-2022-22947', 'Spring Cloud Gateway code injection via actuator endpoint', 'Applications using Spring Cloud Gateway with the Gateway Actuator endpoint enabled and exposed are vulnerable to code injection through crafted routes.', 'CRITICAL', 10.0, 'CISA KEV', '2022-03-03 00:00:00+00', TRUE, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-03 07:00:00+00', '2026-06-03 07:00:00+00'),
  ('35f81189-12d6-5b01-b3bd-1dd58435f1a3', 'CVE-2022-42889', 'Apache Commons Text variable interpolation RCE (Text4Shell)', 'Apache Commons Text 1.5 through 1.9 perform variable interpolation, including script, dns and url lookups, which can lead to arbitrary code execution when untrusted input is interpolated.', 'CRITICAL', 9.8, 'NVD', '2022-10-13 00:00:00+00', TRUE, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-03 17:00:00+00', '2026-06-03 17:00:00+00'),
  ('b8a6af55-0fad-5b70-b478-27cdcfc092a3', 'CVE-2017-5638', 'Apache Struts 2 Jakarta Multipart parser RCE', 'A crafted Content-Type header is evaluated as an OGNL expression by the Jakarta Multipart parser, allowing remote command execution.', 'CRITICAL', 10.0, 'CISA KEV', '2017-03-11 00:00:00+00', TRUE, '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-04 07:00:00+00', '2026-06-04 07:00:00+00'),
  ('5fe0b6df-54b0-549d-8df7-26e18046a540', 'CVE-2018-11776', 'Apache Struts 2 namespace OGNL remote code execution', 'Struts 2 can execute attacker-supplied OGNL when no namespace is set for results or an action chain with wildcard namespaces is used.', 'CRITICAL', 9.8, 'MANUAL', '2018-08-22 00:00:00+00', TRUE, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-04 16:00:00+00', '2026-06-04 16:00:00+00'),
  ('7aa058cd-59cf-506d-b8a8-1eb16cfee4ac', 'CVE-2017-9805', 'Apache Struts 2 REST plugin XStream deserialization RCE', 'The REST plugin uses XStreamHandler to deserialize XML payloads without type filtering, allowing remote code execution via crafted XML.', 'HIGH', 8.1, 'NVD', '2017-09-15 00:00:00+00', TRUE, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-05 01:00:00+00', '2026-06-05 01:00:00+00'),
  ('aa512145-3797-5453-9d79-d349a19dea3d', 'CVE-2014-0160', 'OpenSSL TLS heartbeat information disclosure (Heartbleed)', 'The TLS heartbeat extension in OpenSSL 1.0.1 before 1.0.1g lacks a bounds check, allowing remote attackers to read process memory including private keys.', 'HIGH', 7.5, 'CISA KEV', '2014-04-07 00:00:00+00', FALSE, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-05 15:00:00+00', '2026-07-09 15:00:00+00'),
  ('6b5dd415-a9b4-5f0a-8958-d62b8cdf0114', 'CVE-2022-0778', 'OpenSSL BN_mod_sqrt infinite loop denial of service', 'Parsing a certificate with invalid explicit elliptic-curve parameters can cause an infinite loop in BN_mod_sqrt(), leading to denial of service.', 'HIGH', 7.5, 'Qualys', '2022-03-15 00:00:00+00', TRUE, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-05 23:00:00+00', '2026-06-05 23:00:00+00'),
  ('cb134eef-7fb0-58ec-8179-dc875e3333db', 'CVE-2022-3602', 'OpenSSL X.509 email address buffer overrun', 'A buffer overrun in X.509 certificate verification of name constraints can be triggered by a malicious email address in OpenSSL 3.0.0-3.0.6.', 'HIGH', 7.5, 'Tenable', '2022-11-01 00:00:00+00', TRUE, '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-06 13:00:00+00', '2026-06-06 13:00:00+00'),
  ('58b855e9-fc85-530b-aa68-a3c71ca58f6d', 'CVE-2023-0286', 'OpenSSL X.400 address type confusion', 'A type confusion in X.400 address processing inside a GeneralName can allow reading memory contents or causing denial of service.', 'HIGH', 7.4, 'Rapid7 InsightVM', '2023-02-08 00:00:00+00', TRUE, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-06 22:00:00+00', '2026-06-06 22:00:00+00'),
  ('0fe946f9-0dfa-53af-b0df-38d36754f123', 'CVE-2024-6387', 'OpenSSH sshd signal handler race condition (regreSSHion)', 'A race condition in the sshd signal handler on glibc-based Linux can allow unauthenticated remote code execution as root.', 'HIGH', 8.1, 'NVD', '2024-07-01 00:00:00+00', TRUE, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-07 10:00:00+00', '2026-06-07 10:00:00+00'),
  ('bb38abb8-3e4f-5eee-8377-eaa8bbbbdc5d', 'CVE-2023-48795', 'SSH prefix truncation attack (Terrapin)', 'The SSH transport protocol with certain OpenSSH ciphers and ETM allows a man-in-the-middle to delete handshake messages and downgrade connection security.', 'MEDIUM', 5.9, 'CISA KEV', '2023-12-18 00:00:00+00', TRUE, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-07 21:00:00+00', '2026-06-07 21:00:00+00'),
  ('54972470-cac9-59bd-bc52-96383956f65d', 'CVE-2023-38408', 'OpenSSH ssh-agent PKCS#11 provider code execution', 'The PKCS#11 feature in ssh-agent before OpenSSH 9.3p2 has an insufficiently trustworthy search path, leading to remote code execution if an agent is forwarded to an attacker-controlled system.', 'CRITICAL', 9.8, 'MANUAL', '2023-07-20 00:00:00+00', TRUE, '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-08 08:00:00+00', '2026-06-08 08:00:00+00'),
  ('ddd7208b-5361-5a7a-9a4d-3d4c5e5d83cd', 'CVE-2021-3156', 'sudo heap-based buffer overflow (Baron Samedit)', 'A heap overflow in sudoedit -s allows any local user to gain root privileges without authentication in sudo before 1.9.5p2.', 'HIGH', 7.8, 'NVD', '2021-01-26 00:00:00+00', TRUE, 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-08 21:00:00+00', '2026-06-08 21:00:00+00'),
  ('a37831d6-5106-5eb4-b36c-3ce5e5cbe61a', 'CVE-2021-4034', 'polkit pkexec local privilege escalation (PwnKit)', 'pkexec fails to handle an empty argument vector, allowing an unprivileged local user to gain root by exploiting out-of-bounds read and write.', 'HIGH', 7.8, 'CISA KEV', '2022-01-28 00:00:00+00', TRUE, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-09 06:00:00+00', '2026-06-09 06:00:00+00'),
  ('f605f3d3-2d61-51f9-8da1-a7ba9b49533a', 'CVE-2022-0847', 'Linux kernel pipe buffer flag overwrite (Dirty Pipe)', 'A flaw in the Linux kernel pipe buffer handling allows an unprivileged user to overwrite data in read-only files and escalate privileges.', 'HIGH', 7.8, 'Qualys', '2022-03-10 00:00:00+00', TRUE, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-09 19:00:00+00', '2026-06-09 19:00:00+00'),
  ('00e95d1a-5f0e-561a-9e9a-5f2f37f0b359', 'CVE-2016-5195', 'Linux kernel copy-on-write race condition (Dirty COW)', 'A race condition in the way the Linux kernel handles copy-on-write breakage of private read-only memory mappings allows local privilege escalation.', 'HIGH', 7.0, 'Tenable', '2016-11-10 00:00:00+00', FALSE, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-10 04:00:00+00', '2026-07-27 04:00:00+00'),
  ('58187507-ed21-5a22-ad51-ace9dd7a6781', 'CVE-2023-4911', 'glibc dynamic loader buffer overflow (Looney Tunables)', 'A buffer overflow in ld.so''s processing of the GLIBC_TUNABLES environment variable allows local privilege escalation to root.', 'HIGH', 7.8, 'Rapid7 InsightVM', '2023-10-03 00:00:00+00', TRUE, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-10 13:00:00+00', '2026-06-10 13:00:00+00'),
  ('cd816e70-cdef-50d0-ac66-e079022e7edc', 'CVE-2024-1086', 'Linux kernel nf_tables use-after-free privilege escalation', 'A use-after-free in the netfilter nf_tables component allows a local attacker to gain root privileges.', 'HIGH', 7.8, 'NVD', '2024-01-31 00:00:00+00', TRUE, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-11 04:00:00+00', '2026-06-11 04:00:00+00'),
  ('7ce25e73-73fa-5220-a1e2-4e6d9e8ed947', 'CVE-2023-38545', 'curl SOCKS5 proxy handshake heap buffer overflow', 'A heap overflow in curl before 8.4.0 when the SOCKS5 proxy handshake is slow and a long hostname is passed to the proxy.', 'CRITICAL', 9.8, 'CISA KEV', '2023-10-18 00:00:00+00', TRUE, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-11 14:00:00+00', '2026-06-11 14:00:00+00'),
  ('5dc4ac27-7c37-53bd-8018-528c9a1a5cf2', 'CVE-2014-6271', 'GNU Bash environment variable command injection (Shellshock)', 'GNU Bash through 4.3 processes trailing strings after function definitions in environment variables, allowing remote code execution through CGI and other vectors.', 'CRITICAL', 9.8, 'MANUAL', '2014-09-24 00:00:00+00', TRUE, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-11 22:00:00+00', '2026-06-11 22:00:00+00'),
  ('3081ec4b-f6f1-5b42-91b5-d084f6abc1b7', 'CVE-2024-3094', 'XZ Utils liblzma supply-chain backdoor', 'Malicious code in xz/liblzma 5.6.0 and 5.6.1 release tarballs modifies sshd authentication behaviour through the systemd linkage.', 'CRITICAL', 10.0, 'NVD', '2024-03-29 00:00:00+00', TRUE, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-12 10:00:00+00', '2026-06-12 10:00:00+00'),
  ('98327b78-38d3-50a6-9583-f506f9e24765', 'CVE-2023-44487', 'HTTP/2 Rapid Reset denial of service', 'Clients can abuse HTTP/2 stream cancellation to cause excessive server resource consumption, resulting in a distributed denial of service.', 'HIGH', 7.5, 'CISA KEV', '2023-10-10 00:00:00+00', TRUE, '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-12 23:00:00+00', '2026-06-12 23:00:00+00'),
  ('c1c69ad8-3c0f-5f21-873b-20bf3c54bfad', 'CVE-2021-41773', 'Apache HTTP Server 2.4.49 path traversal and file disclosure', 'A path normalization change in Apache HTTP Server 2.4.49 allows path traversal to files outside the document root.', 'HIGH', 7.5, 'Qualys', '2021-10-05 00:00:00+00', TRUE, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-13 11:00:00+00', '2026-06-13 11:00:00+00'),
  ('3f1ee0a7-3e3b-5a8f-a030-97ebc0b463d6', 'CVE-2021-42013', 'Apache HTTP Server 2.4.49/2.4.50 path traversal and remote code execution', 'The fix for CVE-2021-41773 was insufficient; with mod_cgi enabled, path traversal can lead to remote code execution.', 'CRITICAL', 9.8, 'Tenable', '2021-10-07 00:00:00+00', TRUE, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-13 21:00:00+00', '2026-06-13 21:00:00+00'),
  ('cd400715-be6e-5c0f-a9df-c99faa54762d', 'CVE-2024-4577', 'PHP-CGI argument injection on Windows locales', 'Best-fit character conversion in PHP-CGI allows argument injection that can lead to source disclosure and remote code execution.', 'CRITICAL', 9.8, 'Rapid7 InsightVM', '2024-06-09 00:00:00+00', TRUE, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-14 06:00:00+00', '2026-06-14 06:00:00+00'),
  ('ce1aadd8-63f8-5b40-86ca-4cd4c7055313', 'CVE-2017-0144', 'Microsoft SMBv1 remote code execution (EternalBlue)', 'The SMBv1 server in Windows allows remote code execution via crafted packets; exploited at scale by WannaCry and NotPetya.', 'HIGH', 8.1, 'CISA KEV', '2017-03-16 00:00:00+00', TRUE, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-14 18:00:00+00', '2026-06-14 18:00:00+00'),
  ('cac16ae2-b51a-558f-8a8e-1be25539615b', 'CVE-2020-1472', 'Netlogon elevation of privilege (Zerologon)', 'A flaw in the Netlogon secure channel cryptography allows an unauthenticated attacker with network access to a domain controller to become domain administrator.', 'CRITICAL', 10.0, 'CISA KEV', '2020-08-17 00:00:00+00', TRUE, '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-15 08:00:00+00', '2026-06-15 08:00:00+00'),
  ('5fe1da16-c85b-53cc-8322-9db51ae0ffdf', 'CVE-2021-34527', 'Windows Print Spooler remote code execution (PrintNightmare)', 'The Windows Print Spooler service improperly performs privileged file operations, allowing remote code execution with SYSTEM privileges.', 'HIGH', 8.8, 'CISA KEV', '2021-07-02 00:00:00+00', TRUE, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-15 14:00:00+00', '2026-06-15 14:00:00+00'),
  ('bed92d04-a2b8-5d11-b6a9-a1e401d229fb', 'CVE-2019-0708', 'Remote Desktop Services remote code execution (BlueKeep)', 'A pre-authentication wormable RCE in Remote Desktop Services affecting Windows 7, Server 2008 and Server 2008 R2.', 'CRITICAL', 9.8, 'NVD', '2019-05-16 00:00:00+00', TRUE, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-16 03:00:00+00', '2026-06-16 03:00:00+00'),
  ('841d45e3-f106-570a-a3a6-bd0ab0561bb8', 'CVE-2021-26855', 'Microsoft Exchange Server SSRF (ProxyLogon)', 'A server-side request forgery in Exchange allows an unauthenticated attacker to send arbitrary HTTP requests as the Exchange server; chained into RCE.', 'CRITICAL', 9.8, 'CISA KEV', '2021-03-02 00:00:00+00', TRUE, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-16 13:00:00+00', '2026-06-16 13:00:00+00'),
  ('7ff2229b-37f0-52d4-86c8-0f7fad2609d9', 'CVE-2021-34473', 'Microsoft Exchange Server remote code execution (ProxyShell)', 'Pre-authentication path confusion in Exchange Autodiscover; chained with CVE-2021-34523 and CVE-2021-31207 to achieve remote code execution.', 'CRITICAL', 9.8, 'Qualys', '2021-07-14 00:00:00+00', TRUE, '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-17 03:00:00+00', '2026-06-17 03:00:00+00'),
  ('8f658cfd-be9c-5735-bf1e-f32a118db7b5', 'CVE-2022-41082', 'Microsoft Exchange Server RCE via PowerShell (ProxyNotShell)', 'Authenticated attackers can achieve remote code execution through Exchange PowerShell remoting after chaining with CVE-2022-41040.', 'HIGH', 8.8, 'Tenable', '2022-10-03 00:00:00+00', TRUE, 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-17 13:00:00+00', '2026-06-17 13:00:00+00'),
  ('56304c3f-8120-52c6-974d-5bb45241741d', 'CVE-2018-13379', 'Fortinet FortiOS SSL VPN path traversal', 'A path traversal in the FortiOS SSL VPN web portal allows unauthenticated attackers to download system files, including session files with plaintext credentials.', 'CRITICAL', 9.8, 'CISA KEV', '2019-06-04 00:00:00+00', TRUE, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-17 23:00:00+00', '2026-06-17 23:00:00+00'),
  ('f575af87-a1c8-55eb-b773-d2fbaf36186d', 'CVE-2022-40684', 'Fortinet FortiOS and FortiProxy authentication bypass', 'An authentication bypass on the administrative interface using alternate path or channel allows unauthenticated administrative operations via crafted HTTP requests.', 'CRITICAL', 9.8, 'CISA KEV', '2022-10-18 00:00:00+00', TRUE, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-18 10:00:00+00', '2026-06-18 10:00:00+00'),
  ('5222046d-740c-5ab2-a316-63a341d62d6f', 'CVE-2023-27997', 'Fortinet FortiOS SSL-VPN pre-authentication heap overflow', 'A heap-based buffer overflow in FortiOS SSL-VPN allows a remote attacker to execute arbitrary code via crafted requests.', 'CRITICAL', 9.8, 'CISA KEV', '2023-06-13 00:00:00+00', TRUE, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-19 00:00:00+00', '2026-06-19 00:00:00+00'),
  ('9b7cc5f8-3f4d-583d-ab3d-19c5a92502fa', 'CVE-2024-21762', 'Fortinet FortiOS SSL VPN out-of-bounds write', 'An out-of-bounds write in sslvpnd allows a remote unauthenticated attacker to execute arbitrary code via specially crafted HTTP requests.', 'CRITICAL', 9.6, 'MANUAL', '2024-02-09 00:00:00+00', TRUE, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-19 08:00:00+00', '2026-06-19 08:00:00+00');
INSERT INTO vulnerabilities (id, cve_id, title, description, severity, cvss_score, source, published_at, is_active, created_by, created_at, updated_at) VALUES
  ('1347661c-e0b9-5227-9b29-39b470771a9b', 'CVE-2022-1388', 'F5 BIG-IP iControl REST authentication bypass', 'Undisclosed requests to BIG-IP iControl REST can bypass authentication and allow arbitrary command execution as root.', 'CRITICAL', 9.8, 'CISA KEV', '2022-05-05 00:00:00+00', TRUE, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-19 17:00:00+00', '2026-06-19 17:00:00+00'),
  ('668d2e0f-e208-541a-b52e-d7c44a2f3699', 'CVE-2023-46747', 'F5 BIG-IP Configuration utility authentication bypass', 'An unauthenticated attacker with network access to the BIG-IP management port can achieve remote code execution through the Configuration utility.', 'CRITICAL', 9.8, 'CISA KEV', '2023-10-26 00:00:00+00', TRUE, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-20 08:00:00+00', '2026-06-20 08:00:00+00'),
  ('9c33f510-665d-5b4a-a095-96cbaacc9841', 'CVE-2019-19781', 'Citrix ADC and Gateway directory traversal', 'A directory traversal vulnerability allows unauthenticated attackers to execute arbitrary code on Citrix ADC and Gateway appliances.', 'CRITICAL', 9.8, 'CISA KEV', '2019-12-27 00:00:00+00', TRUE, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-20 15:00:00+00', '2026-06-20 15:00:00+00'),
  ('31cdfed6-8c76-56f6-86d5-7e013852f99b', 'CVE-2023-3519', 'Citrix ADC and Gateway unauthenticated remote code execution', 'Unauthenticated RCE on Citrix NetScaler ADC and Gateway configured as a gateway (VPN, ICA Proxy, RDP Proxy) or AAA virtual server.', 'CRITICAL', 9.8, 'CISA KEV', '2023-07-19 00:00:00+00', TRUE, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-21 07:00:00+00', '2026-06-21 07:00:00+00'),
  ('aab6b97b-9ca2-5096-839f-287611eaa1f0', 'CVE-2024-3400', 'Palo Alto PAN-OS GlobalProtect command injection', 'A command injection from arbitrary file creation in the GlobalProtect feature of PAN-OS lets an unauthenticated attacker execute code with root privileges on the firewall.', 'CRITICAL', 10.0, 'CISA KEV', '2024-04-12 00:00:00+00', TRUE, '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-21 15:00:00+00', '2026-06-21 15:00:00+00'),
  ('2be7d6fc-e050-5a7b-84e9-fc665feb86ee', 'CVE-2023-20198', 'Cisco IOS XE web UI privilege escalation', 'A flaw in the web UI feature of Cisco IOS XE lets a remote unauthenticated attacker create an account with privilege level 15.', 'CRITICAL', 10.0, 'CISA KEV', '2023-10-16 00:00:00+00', TRUE, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-22 02:00:00+00', '2026-06-22 02:00:00+00'),
  ('9e174df8-7fd3-549f-958b-ce63f65685ba', 'CVE-2024-23897', 'Jenkins CLI arbitrary file read', 'Jenkins 2.441 and earlier use the args4j library, which replaces ''@'' followed by a file path with the file contents, allowing unauthenticated reads of arbitrary files.', 'CRITICAL', 9.8, 'CISA KEV', '2024-01-24 00:00:00+00', TRUE, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-22 16:00:00+00', '2026-06-22 16:00:00+00'),
  ('61d08b18-cebf-5425-85e9-b0d1f06b63e5', 'CVE-2021-22205', 'GitLab ExifTool image upload remote code execution', 'An unauthenticated attacker can achieve RCE through image parsing of crafted DjVu files uploaded to GitLab CE/EE.', 'CRITICAL', 10.0, 'MANUAL', '2021-04-23 00:00:00+00', TRUE, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-22 23:00:00+00', '2026-06-22 23:00:00+00'),
  ('1c5a9019-aff0-5d59-82a8-7077c49ed792', 'CVE-2023-42793', 'JetBrains TeamCity authentication bypass', 'In JetBrains TeamCity before 2023.05.4, authentication bypass allows remote code execution on the server.', 'CRITICAL', 9.8, 'NVD', '2023-09-19 00:00:00+00', TRUE, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-23 14:00:00+00', '2026-06-23 14:00:00+00'),
  ('d9a11818-d1b0-5a04-a62d-8e6fa8b5bbea', 'CVE-2022-26134', 'Atlassian Confluence OGNL injection', 'An OGNL injection allows an unauthenticated attacker to execute arbitrary code on Confluence Server and Data Center.', 'CRITICAL', 9.8, 'CISA KEV', '2022-06-03 00:00:00+00', TRUE, '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-24 00:00:00+00', '2026-06-24 00:00:00+00'),
  ('0a85251c-70a2-5846-9be4-720052f30a13', 'CVE-2023-22515', 'Atlassian Confluence Data Center broken access control', 'Unauthenticated attackers can create Confluence administrator accounts and access the instance via the setup endpoints.', 'CRITICAL', 10.0, 'Qualys', '2023-10-04 00:00:00+00', TRUE, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-24 12:00:00+00', '2026-06-24 12:00:00+00'),
  ('91c44b27-afab-5ba0-8cb3-78a54e46cfdf', 'CVE-2023-34362', 'Progress MOVEit Transfer SQL injection', 'An SQL injection in MOVEit Transfer''s web application allows an unauthenticated attacker to access the database and execute arbitrary code.', 'CRITICAL', 9.8, 'CISA KEV', '2023-06-02 00:00:00+00', TRUE, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-24 23:00:00+00', '2026-06-24 23:00:00+00'),
  ('4e5037a2-1ef6-5a32-9b3c-9af565f2286d', 'CVE-2023-2868', 'Barracuda Email Security Gateway command injection', 'A remote command injection in the TAR file attachment scanning of Barracuda ESG 5.1.3.001 through 9.2.0.006.', 'CRITICAL', 9.8, 'Rapid7 InsightVM', '2023-05-24 00:00:00+00', TRUE, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-25 09:00:00+00', '2026-06-25 09:00:00+00'),
  ('8cb37374-1655-5c03-b095-8be0288f19ab', 'CVE-2019-11510', 'Pulse Connect Secure pre-authentication arbitrary file read', 'An unauthenticated remote attacker can send a crafted URI to read arbitrary files, including cached credentials, on Pulse Connect Secure.', 'CRITICAL', 10.0, 'NVD', '2019-05-08 00:00:00+00', TRUE, '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-25 20:00:00+00', '2026-06-25 20:00:00+00'),
  ('02da42f6-fb1e-5253-b877-0b02ae794577', 'CVE-2023-4863', 'libwebp heap buffer overflow in WebP lossless decoding', 'A heap overflow in the WebP image library lets a remote attacker perform an out-of-bounds memory write via a crafted WebP image.', 'HIGH', 8.8, 'CISA KEV', '2023-09-12 00:00:00+00', TRUE, 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-26 08:00:00+00', '2026-06-26 08:00:00+00'),
  ('37f2755b-e9c1-5ea5-9fe9-967e15716b0d', 'CVE-2020-0601', 'Windows CryptoAPI spoofing vulnerability (CurveBall)', 'crypt32.dll fails to validate ECC certificates properly, allowing attackers to spoof code-signing certificates and TLS trust.', 'HIGH', 8.1, 'MANUAL', '2020-01-14 00:00:00+00', TRUE, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-26 18:00:00+00', '2026-06-26 18:00:00+00'),
  ('bf272130-a856-5491-80da-153e8d981f66', 'CVE-2022-30190', 'Microsoft Support Diagnostic Tool RCE (Follina)', 'A remote code execution vulnerability exists when MSDT is called via the URL protocol from an application such as Word.', 'HIGH', 7.8, 'NVD', '2022-06-01 00:00:00+00', TRUE, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-27 06:00:00+00', '2026-06-27 06:00:00+00'),
  ('728cd404-40fc-53b5-bd9d-2f2205bcedec', 'CVE-2023-23397', 'Microsoft Outlook elevation of privilege via NTLM leak', 'A crafted calendar item with a UNC path causes Outlook to leak the user''s Net-NTLMv2 hash without user interaction.', 'CRITICAL', 9.8, 'CISA KEV', '2023-03-14 00:00:00+00', TRUE, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-27 13:00:00+00', '2026-06-27 13:00:00+00'),
  ('4f95a61d-1699-5a7e-87b3-80398b1039a9', 'CVE-2021-3449', 'OpenSSL TLS renegotiation NULL pointer dereference', 'A maliciously crafted renegotiation ClientHello message can crash an OpenSSL TLSv1.2 server.', 'MEDIUM', 5.9, 'Qualys', '2021-03-25 00:00:00+00', FALSE, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-28 01:00:00+00', '2026-08-01 01:00:00+00'),
  ('1e0d2537-361a-5b7d-b549-7ec5b991544c', 'CVE-2022-41741', 'nginx ngx_http_mp4_module memory corruption', 'A specially crafted mp4 file can cause memory corruption in the ngx_http_mp4_module worker process.', 'HIGH', 7.8, 'Tenable', '2022-10-19 00:00:00+00', TRUE, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-10-21 10:40:00+00', '2026-10-21 10:40:00+00');
