INSERT INTO solutions (id, title, description, is_retired, current_version_id, created_by, created_at, updated_at) VALUES
  ('12cf2791-3f0c-5f1f-9783-ff15d15cb455', 'Pre-patch EBS snapshot (AWS SSM Automation)', 'Creates EBS snapshots of all attached volumes before any change, tagged with the incident number for rollback.', FALSE, NULL, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-02 12:00:00+00', '2026-06-02 12:00:00+00'),
  ('f44a1bf5-095b-5af4-a0d1-0831a7dce830', 'Pre-patch VM snapshot (vSphere)', 'Takes a quiesced VMware snapshot before patching on-prem Windows servers; snapshot retained for 72 hours.', FALSE, NULL, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-02 22:00:00+00', '2026-06-02 22:00:00+00'),
  ('9775b6f5-49db-540e-9aaa-1dd994b96fd4', 'Drain node from load balancer', 'Sets the F5 pool member to disabled and waits for active connections to drop to zero.', FALSE, NULL, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-03 08:00:00+00', '2026-06-03 08:00:00+00'),
  ('7903d7ea-a4ce-57ac-b38a-2a2b885e3b63', 'Restart application service', 'Graceful restart of the application service via systemd with a 60s stop timeout, then waits for the listening port.', FALSE, NULL, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-03 23:00:00+00', '2026-06-03 23:00:00+00'),
  ('f52ae7a0-d2e7-5d60-ac2f-fabd006f39c8', 'Post-patch health check', 'Calls the service health endpoint and fails the step if the response is not HTTP 200 with status UP within 2 minutes.', FALSE, NULL, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-04 06:00:00+00', '2026-06-04 06:00:00+00'),
  ('59702804-50da-5d8c-abd7-d104994fcb46', 'Post-patch vulnerability rescan (Qualys)', 'Launches an authenticated Qualys scan on the asset and fails if the CVE is still detected.', FALSE, NULL, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-04 18:00:00+00', '2026-06-04 18:00:00+00'),
  ('b5848ff9-4210-5a8a-b098-1389ee15f278', 'Rolling reboot within maintenance window', 'Reboots the host, waits for SSH/WinRM to return and verifies uptime; refuses to run outside the approved window.', FALSE, NULL, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-05 04:00:00+00', '2026-06-05 04:00:00+00'),
  ('e24bed3c-60f8-587d-b268-800366ace85e', 'Upgrade Log4j2 to 2.17.2 across Java services', 'Replaces log4j-core and log4j-api jars, removes the JndiLookup class from shaded jars, and restarts the container.', FALSE, NULL, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-05 19:00:00+00', '2026-08-12 11:15:00+00'),
  ('73cdb457-00af-5cb0-ba75-e1ddd6bebce1', 'Interim mitigation: remove JndiLookup class from log4j-core', 'Zips out org/apache/logging/log4j/core/lookup/JndiLookup.class and sets -Dlog4j2.formatMsgNoLookups=true until the upgrade lands.', TRUE, NULL, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-06 04:00:00+00', '2026-07-06 04:00:00+00'),
  ('17509db8-94ee-516a-ab45-de245c6266ce', 'Upgrade Spring Framework to 5.3.18', 'Updates spring-framework BOM and redeploys the application artifact built by CI.', FALSE, NULL, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-06 13:00:00+00', '2026-06-06 13:00:00+00'),
  ('ebf87035-917c-58a4-8c70-15145b33b1e5', 'Upgrade Spring Cloud Function and Gateway', 'Upgrades spring-cloud-function to 3.2.3 and spring-cloud-gateway to 3.1.1, then disables the exposed gateway actuator endpoint.', FALSE, NULL, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-07 04:00:00+00', '2026-10-15 11:15:00+00'),
  ('1a16aba6-d991-597f-8701-158a733af2d1', 'Upgrade Apache Commons Text to 1.10.0', 'Bumps commons-text to 1.10.0 where the interpolation defaults are safe and rebuilds the service.', FALSE, NULL, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-07 13:00:00+00', '2026-06-07 13:00:00+00'),
  ('b6bef499-7076-5513-87a4-05aa14431270', 'Upgrade Apache Struts to 2.5.33', 'Replaces struts2-core and plugins, validates the struts.xml namespace configuration and redeploys the WAR.', FALSE, NULL, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-07 22:00:00+00', '2026-09-09 11:15:00+00'),
  ('d1371b91-8425-5ef6-b1c2-781c1a7f7ed0', 'WAF virtual patch for Struts OGNL injection', 'Pushes an F5 ASM signature set that blocks OGNL expressions in Content-Type and namespace parameters.', TRUE, NULL, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-08 12:00:00+00', '2026-07-08 12:00:00+00'),
  ('5ef47b53-e74c-5696-84db-674c89a20d6c', 'Upgrade OpenSSL via OS package manager', 'Applies the vendor security update for openssl/libssl using apt or dnf, then restarts services linked to libssl with needrestart.', FALSE, NULL, '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-08 20:00:00+00', '2026-06-08 20:00:00+00'),
  ('d8099603-43d3-5be2-8c11-5a129c34ed2b', 'Upgrade OpenSSH server to 9.8p1', 'Installs the vendor-backported OpenSSH build, validates sshd_config with sshd -t and reloads sshd without dropping sessions.', FALSE, NULL, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-09 07:00:00+00', '2026-10-14 11:15:00+00'),
  ('8f160588-2012-5ea0-a69a-3d553c0000f2', 'Harden SSH ciphers (Terrapin mitigation)', 'Disables chacha20-poly1305 and *-etm MACs in sshd_config and ssh_config until both ends support strict key exchange.', FALSE, NULL, '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-09 21:00:00+00', '2026-06-09 21:00:00+00'),
  ('74b6095d-833b-5233-b1b6-048ebc2a7ea7', 'Patch sudo to 1.9.5p2 or later', 'Upgrades the sudo package and verifies the version string and /etc/sudoers syntax with visudo -c.', FALSE, NULL, '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-10 05:00:00+00', '2026-06-10 05:00:00+00'),
  ('7f4d5dc4-37c9-524e-b9a6-dc936a3e8dc2', 'Apply OS security errata (polkit, glibc, bash)', 'Installs security-classified updates only (yum --security / unattended-upgrade) and records the advisories applied.', FALSE, NULL, 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-10 17:00:00+00', '2026-06-10 17:00:00+00'),
  ('0cac83b3-ffef-5c22-9c92-cbaa631a2a68', 'Kernel security update with staged reboot', 'Installs the latest kernel from the vendor repo, sets it as default in GRUB and schedules a reboot in the next maintenance window.', FALSE, NULL, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-11 07:00:00+00', '2026-10-06 11:15:00+00'),
  ('2099971c-cd36-5b70-962a-7ed106d56893', 'Upgrade curl and libcurl to 8.4.0 or later', 'Updates curl/libcurl packages and checks the SOCKS5 hostname handling regression test.', FALSE, NULL, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-11 16:00:00+00', '2026-08-25 11:15:00+00'),
  ('1c24cc73-5459-5c3e-bb03-c04e237a88a2', 'Downgrade xz-utils to 5.4.6', 'Removes the affected xz 5.6.0/5.6.1 packages, installs 5.4.6 and restarts sshd.', FALSE, NULL, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-12 05:00:00+00', '2026-06-12 05:00:00+00'),
  ('bb2db354-5b56-53f0-a6a4-8ed6b58870ff', 'nginx HTTP/2 rapid reset mitigation', 'Sets keepalive_requests 1000 and http2_max_concurrent_streams 128, validates with nginx -t and reloads.', FALSE, NULL, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-12 13:00:00+00', '2026-06-12 13:00:00+00'),
  ('e785d04c-afc0-524e-9d4a-0b09d84c20b7', 'Upgrade nginx to 1.25.3', 'Installs nginx from the official repository, performs a binary upgrade (USR2) without dropping connections.', FALSE, NULL, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-13 03:00:00+00', '2026-09-18 11:15:00+00'),
  ('f46d1d57-b402-5088-a80a-cbc8db7de1c4', 'Upgrade Apache HTTP Server to 2.4.58', 'Upgrades httpd, removes legacy ''Require all granted'' on / and restarts the service gracefully.', FALSE, NULL, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-13 10:00:00+00', '2026-06-13 10:00:00+00'),
  ('0ebab7f6-ba6d-55fa-a92d-4b6a18f6983f', 'Upgrade PHP to 8.2.20', 'Upgrades PHP and PHP-FPM, disables the CGI SAPI where not required.', FALSE, NULL, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-13 21:00:00+00', '2026-06-13 21:00:00+00'),
  ('a2b46581-9f8c-52e4-a84e-60bfb0510af3', 'Disable SMBv1 and apply MS17-010', 'Removes the SMB1Protocol feature, installs KB4012212/KB4012215 where missing and reports SMB signing state.', FALSE, NULL, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-14 10:00:00+00', '2026-06-14 10:00:00+00'),
  ('344b3f08-5e67-5d68-8edd-56190224636e', 'Netlogon secure channel enforcement (Zerologon)', 'Installs the August 2020 cumulative update and sets FullSecureChannelProtection=1 on domain controllers.', FALSE, NULL, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-14 20:00:00+00', '2026-06-14 20:00:00+00'),
  ('2092e870-9251-5b27-941e-a2e949a5b1ba', 'Disable Print Spooler on non-print servers', 'Stops and disables the Spooler service on domain controllers and file servers, and installs the July 2021 out-of-band update.', FALSE, NULL, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-15 07:00:00+00', '2026-06-15 07:00:00+00'),
  ('56c2e81c-f53b-54eb-87bc-ff5cba6a2ace', 'Enable NLA and install BlueKeep patch', 'Requires Network Level Authentication and installs KB4499175 for Server 2008 R2.', FALSE, NULL, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-15 21:00:00+00', '2026-06-15 21:00:00+00'),
  ('e0e3c825-c4eb-54fa-b0bd-73c624937729', 'Install Exchange Server Security Update', 'Puts the DAG member in maintenance mode, installs the cumulative security update, runs health checks and exits maintenance mode.', FALSE, NULL, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-16 04:00:00+00', '2026-09-21 11:15:00+00'),
  ('e688b2e4-f2ad-5b7e-a885-be31b64e1f3c', 'Windows cumulative update via WSUS', 'Approves and installs the latest cumulative update for the target group and reports pending reboot state.', FALSE, NULL, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-16 15:00:00+00', '2026-10-17 11:15:00+00'),
  ('6c865fb9-1c0f-5cfb-8e6c-f39c71b27015', 'Upgrade FortiOS to 7.2.8 via FortiManager', 'Stages the firmware on FortiManager and triggers a rolling HA upgrade with automatic config backup.', FALSE, NULL, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-17 03:00:00+00', '2026-10-19 11:15:00+00'),
  ('4c8f4d47-0adf-59d2-9885-3cbe8a5af4a2', 'Upgrade BIG-IP to 15.1.10.2 via iControl', 'Installs the target software volume, copies the configuration and activates it on the standby unit first.', FALSE, NULL, '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-17 16:00:00+00', '2026-06-17 16:00:00+00'),
  ('988e2957-d738-5957-aff3-079d01e68522', 'Upgrade NetScaler ADC to 13.1-49.15', 'Uploads the build, runs the pre-upgrade validation and performs a staged HA failover upgrade.', FALSE, NULL, '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-18 04:00:00+00', '2026-06-18 04:00:00+00'),
  ('cfc5bcbd-d37b-5efd-9366-cc0dd3770839', 'Apply PAN-OS 10.2.9-h1 hotfix', 'Downloads and installs the hotfix on the passive HA peer, fails over, then upgrades the former active unit.', FALSE, NULL, '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-18 11:00:00+00', '2026-06-18 11:00:00+00'),
  ('e973a712-9fb1-5704-850b-8a45ab94b7a8', 'Upgrade IOS XE and disable HTTP server', 'Installs the fixed IOS XE image in install mode and applies ''no ip http server / no ip http secure-server''.', FALSE, NULL, '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-18 23:00:00+00', '2026-06-18 23:00:00+00'),
  ('7546bcba-3e87-5936-ad0e-20023ada3214', 'Upgrade Jenkins to 2.442 LTS', 'Replaces jenkins.war, backs up JENKINS_HOME and restarts after quiescing running builds.', FALSE, NULL, 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-19 11:00:00+00', '2026-06-19 11:00:00+00'),
  ('681b691a-785c-5d11-89dd-fa8490913642', 'Upgrade GitLab to 13.10.3', 'Runs the omnibus upgrade path with background migrations check, then verifies repository integrity.', FALSE, NULL, 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-20 00:00:00+00', '2026-06-20 00:00:00+00'),
  ('8a93a5dc-9817-5a66-9bb8-d4a8ad46b75a', 'Upgrade TeamCity to 2023.05.4', 'Applies the TeamCity patch plugin and restarts the server; fallback is the full distribution upgrade.', FALSE, NULL, '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-20 09:00:00+00', '2026-06-20 09:00:00+00');
INSERT INTO solutions (id, title, description, is_retired, current_version_id, created_by, created_at, updated_at) VALUES
  ('006953f7-2bc4-57ba-8cac-76f2cdd2fe8f', 'Upgrade Confluence Data Center to 8.5.3', 'Rolling node upgrade using zero-downtime mode; the setup endpoints are blocked at the reverse proxy first.', FALSE, NULL, 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-20 22:00:00+00', '2026-06-20 22:00:00+00'),
  ('5d99d139-7d01-5bba-a91a-4b8ea1df50cf', 'Apply MOVEit Transfer security patch', 'Disables HTTP/HTTPS traffic, installs the vendor patch, validates files and re-enables traffic.', FALSE, NULL, '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-21 05:00:00+00', '2026-06-21 05:00:00+00'),
  ('0b09a43c-8065-58d5-90a6-000875bbf745', 'Barracuda ESG security patch (BNSF-36456)', 'Triggers the Barracuda central update service to download and apply the security patch and reboot.', FALSE, NULL, 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-21 17:00:00+00', '2026-06-21 17:00:00+00'),
  ('ebf5f50f-ee3b-5f07-86d9-1a033284d120', 'Upgrade Pulse Connect Secure to 9.1R18', 'Uploads the package via the admin API and installs it with automatic rollback if the health probe fails.', FALSE, NULL, '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-22 06:00:00+00', '2026-06-22 06:00:00+00'),
  ('28441d9e-7f54-5777-86d9-02e266e1afe7', 'Rebuild Node images with libwebp 1.3.2 (sharp 0.32.6)', 'Bumps sharp to 0.32.6 in the lockfile, rebuilds the container image and rolls it out through the CD pipeline.', FALSE, NULL, 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-22 14:00:00+00', '2026-06-22 14:00:00+00'),
  ('4871a3d3-7744-5518-b82c-abc2f7feff8d', 'Disable TLS 1.0/1.1 on load balancers', 'Removes legacy TLS protocol versions from all client-ssl profiles on BIG-IP.', FALSE, NULL, '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-23 02:00:00+00', '2026-08-30 11:15:00+00'),
  ('47c8c805-24a3-5a8d-a56f-14273e0c1c08', 'CIS baseline: SSH configuration hardening', 'Applies CIS Level 1 sshd_config settings: PermitRootLogin no, MaxAuthTries 4, ClientAliveInterval 300.', FALSE, NULL, '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-23 15:00:00+00', '2026-06-23 15:00:00+00'),
  ('8aba28f0-5f16-5413-a2d6-d350027651b7', 'Rotate service account credentials in Vault', 'Rotates database and API service account secrets in HashiCorp Vault and restarts consumers with the new lease.', FALSE, NULL, 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-23 23:00:00+00', '2026-06-23 23:00:00+00'),
  ('637c07c7-e6ca-524d-ab21-7461b39ef63f', 'Rebuild container base images with patched OpenSSL', 'Triggers the CI pipeline to rebuild all base images from the latest patched distro layers and opens deployment PRs.', FALSE, NULL, 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-24 12:00:00+00', '2026-06-24 12:00:00+00'),
  ('7faa0ef5-5069-59a2-9915-a537bea73564', 'Rotate expiring TLS certificates in ACM', 'Requests renewed certificates in AWS Certificate Manager and updates the load balancer listeners.', FALSE, NULL, '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-24 22:00:00+00', '2026-06-24 22:00:00+00'),
  ('312e5cc9-f0cc-586f-9907-bf83d49f2c04', 'Deploy Windows LAPS to member servers', 'Installs and configures Windows LAPS so local administrator passwords are unique and rotated every 30 days.', FALSE, NULL, 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-25 11:00:00+00', '2026-06-25 11:00:00+00'),
  ('d256e48b-e6b3-5cea-8de5-698fb8a2206d', 'Block Confluence setup endpoints at reverse proxy (interim)', 'Adds a deny rule for /setup/* paths on the nginx reverse proxy in front of Confluence until the upgrade is done.', FALSE, NULL, '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-25 21:00:00+00', '2026-06-25 21:00:00+00');
INSERT INTO solution_versions (id, solution_id, version_no, title, description, executor, job_spec, applies_to, risk_level, requires_reboot, timeout_seconds, max_retries, status, created_by, created_at) VALUES
  ('330cfbb4-1164-5103-afc0-bf949498913c', '12cf2791-3f0c-5f1f-9783-ff15d15cb455', 1, 'Pre-patch EBS snapshot (AWS SSM Automation)', 'Creates EBS snapshots of all attached volumes before any change, tagged with the incident number for rollback.', 'AWS_SSM', '{"document": "AWS-CreateSnapshot", "parameters": {"VolumeId": ["{{volume_ids}}"], "Description": ["bulwark pre-patch {{incident_code}}"]}}'::jsonb, 'AWS EC2 instances', 'LOW', FALSE, 900, 1, 'APPROVED', 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-02 12:00:00+00'),
  ('4febd224-2911-5c8c-939e-9143c1e5d458', 'f44a1bf5-095b-5af4-a0d1-0831a7dce830', 1, 'Pre-patch VM snapshot (vSphere)', 'Takes a quiesced VMware snapshot before patching on-prem Windows servers; snapshot retained for 72 hours.', 'ANSIBLE', '{"playbook": "playbooks/vmware/snapshot_create.yml", "inventory": "inventory/vcenter.yml", "extra_vars": {"quiesce": true, "retention_hours": 72}}'::jsonb, 'On-prem VMware guests', 'LOW', FALSE, 900, 1, 'APPROVED', '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-02 22:00:00+00'),
  ('0b383272-bd3d-533c-bc81-f5a38edaf1ef', '9775b6f5-49db-540e-9aaa-1dd994b96fd4', 1, 'Drain node from load balancer', 'Sets the F5 pool member to disabled and waits for active connections to drop to zero.', 'HTTP', '{"method": "PATCH", "url": "https://lb-f5-01.corp.example.com/mgmt/tm/ltm/pool/~Common~{{pool}}/members/{{member}}", "body": {"session": "user-disabled"}, "expect_status": 200}'::jsonb, 'Servers behind F5 pools', 'LOW', FALSE, 600, 0, 'APPROVED', 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-03 08:00:00+00'),
  ('0c24aaa5-2d7f-56e3-8b3a-6504581e788e', '7903d7ea-a4ce-57ac-b38a-2a2b885e3b63', 1, 'Restart application service', 'Graceful restart of the application service via systemd with a 60s stop timeout, then waits for the listening port.', 'SHELL', '{"command": "systemctl restart {{service}} && timeout 120 bash -c ''until ss -ltn | grep -q :{{port}}; do sleep 2; done''", "shell": "bash", "become": true}'::jsonb, 'Linux services', 'MEDIUM', FALSE, 300, 1, 'APPROVED', '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-03 23:00:00+00'),
  ('c1f95511-9ffa-5445-bbd9-982311c9ecfb', 'f52ae7a0-d2e7-5d60-ac2f-fabd006f39c8', 1, 'Post-patch health check', 'Calls the service health endpoint and fails the step if the response is not HTTP 200 with status UP within 2 minutes.', 'HTTP', '{"method": "GET", "url": "https://{{hostname}}/actuator/health", "expect_status": 200, "expect_json": {"status": "UP"}, "retries": 6, "retry_delay_seconds": 20}'::jsonb, 'All HTTP services', 'LOW', FALSE, 180, 0, 'APPROVED', 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-04 06:00:00+00'),
  ('da00a605-3300-5ac2-afa1-f7c61580c42f', '59702804-50da-5d8c-abd7-d104994fcb46', 1, 'Post-patch vulnerability rescan (Qualys)', 'Launches an authenticated Qualys scan on the asset and fails if the CVE is still detected.', 'HTTP', '{"method": "POST", "url": "https://qualysapi.qg3.apps.qualys.com/api/2.0/fo/scan/", "params": {"action": "launch", "scan_title": "bulwark-{{incident_code}}", "ip": "{{ip}}", "option_id": "1234567"}, "poll": true}'::jsonb, 'All assets', 'LOW', FALSE, 1800, 0, 'APPROVED', '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-04 18:00:00+00'),
  ('f6f257ad-1148-5bcd-a588-81aa8c31b5f4', 'b5848ff9-4210-5a8a-b098-1389ee15f278', 1, 'Rolling reboot within maintenance window', 'Reboots the host, waits for SSH/WinRM to return and verifies uptime; refuses to run outside the approved window.', 'ANSIBLE', '{"playbook": "playbooks/common/reboot_and_wait.yml", "extra_vars": {"reboot_timeout": 600, "enforce_window": true}}'::jsonb, 'Linux and Windows servers', 'HIGH', TRUE, 900, 1, 'APPROVED', 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-05 04:00:00+00'),
  ('ee004497-8f2f-52ce-91ba-3d5cb3e9459d', 'e24bed3c-60f8-587d-b268-800366ace85e', 1, 'Upgrade Log4j2 to 2.17.2 across Java services', 'Replaces log4j-core and log4j-api jars, removes the JndiLookup class from shaded jars, and restarts the container.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_log4j.yml", "extra_vars": {"log4j_version": "2.17.1", "remove_jndilookup": true}}'::jsonb, 'Java 8/11/17 services', 'MEDIUM', FALSE, 1200, 1, 'APPROVED', '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-05 19:00:00+00'),
  ('865766c9-ac06-5742-9b09-1ef2b0723f65', 'e24bed3c-60f8-587d-b268-800366ace85e', 2, 'Upgrade Log4j2 to 2.17.2 across Java services', 'Replaces log4j-core and log4j-api jars, removes the JndiLookup class from shaded jars, and restarts the container. Revision 2: Bump target to 2.17.2 (CVE-2021-44832 fix).', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_log4j.yml", "extra_vars": {"log4j_version": "2.17.2", "remove_jndilookup": true}}'::jsonb, 'Java 8/11/17 services', 'MEDIUM', FALSE, 1200, 1, 'APPROVED', '21909828-61d4-5921-bcaa-2f11151dab91', '2026-08-12 11:15:00+00'),
  ('7bcdcaa1-0b72-529e-9b01-13fa1e44718e', '73cdb457-00af-5cb0-ba75-e1ddd6bebce1', 1, 'Interim mitigation: remove JndiLookup class from log4j-core', 'Zips out org/apache/logging/log4j/core/lookup/JndiLookup.class and sets -Dlog4j2.formatMsgNoLookups=true until the upgrade lands.', 'SHELL', '{"command": "find {{app_dir}} -name ''log4j-core-*.jar'' -exec zip -q -d {} org/apache/logging/log4j/core/lookup/JndiLookup.class \\;", "shell": "bash", "become": true}'::jsonb, 'Log4j 2.0-2.14.1', 'LOW', FALSE, 300, 0, 'APPROVED', '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-06 04:00:00+00'),
  ('7395d5fa-081f-5cc8-92ce-1f4aae06fcf7', '17509db8-94ee-516a-ab45-de245c6266ce', 1, 'Upgrade Spring Framework to 5.3.18', 'Updates spring-framework BOM and redeploys the application artifact built by CI.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_spring_framework.yml", "extra_vars": {"spring_framework_version": "5.3.18"}}'::jsonb, 'Spring MVC / WebFlux apps', 'MEDIUM', FALSE, 1500, 1, 'APPROVED', 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-06 13:00:00+00'),
  ('96553b40-bb42-5f6c-9df6-fbf591422204', 'ebf87035-917c-58a4-8c70-15145b33b1e5', 1, 'Upgrade Spring Cloud Function and Gateway', 'Upgrades spring-cloud-function to 3.2.3 and spring-cloud-gateway to 3.1.1, then disables the exposed gateway actuator endpoint.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_spring_cloud.yml", "extra_vars": {"function_version": "3.2.3", "gateway_version": "3.1.1", "disable_gateway_actuator": true}}'::jsonb, 'Spring Cloud apps', 'MEDIUM', FALSE, 1500, 1, 'APPROVED', 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-07 04:00:00+00'),
  ('c3d46869-6cf1-5a3d-9ad2-ab826b3be842', 'ebf87035-917c-58a4-8c70-15145b33b1e5', 2, 'Upgrade Spring Cloud Function and Gateway', 'Upgrades spring-cloud-function to 3.2.3 and spring-cloud-gateway to 3.1.1, then disables the exposed gateway actuator endpoint. Revision 2: Add canary deployment and automatic rollback.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_spring_cloud.yml", "extra_vars": {"function_version": "3.2.3", "gateway_version": "3.1.2", "canary_percent": 10}}'::jsonb, 'Spring Cloud apps', 'MEDIUM', FALSE, 1500, 1, 'REVIEW_PENDING', 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-10-15 11:15:00+00'),
  ('c892ad5c-24bc-590d-9ce5-2d7338948f00', '1a16aba6-d991-597f-8701-158a733af2d1', 1, 'Upgrade Apache Commons Text to 1.10.0', 'Bumps commons-text to 1.10.0 where the interpolation defaults are safe and rebuilds the service.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_dependency.yml", "extra_vars": {"group": "org.apache.commons", "artifact": "commons-text", "version": "1.10.0"}}'::jsonb, 'Java apps', 'LOW', FALSE, 1200, 0, 'APPROVED', '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-07 13:00:00+00'),
  ('6dc2d6d7-fd90-5407-8a08-daf2598dc0c5', 'b6bef499-7076-5513-87a4-05aa14431270', 1, 'Upgrade Apache Struts to 2.5.33', 'Replaces struts2-core and plugins, validates the struts.xml namespace configuration and redeploys the WAR.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_struts.yml", "extra_vars": {"struts_version": "2.5.33"}}'::jsonb, 'Struts 2.x web apps on Tomcat', 'HIGH', FALSE, 1800, 1, 'APPROVED', 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-07 22:00:00+00'),
  ('741f5955-49e1-569b-924b-9d3df1c4f42f', 'b6bef499-7076-5513-87a4-05aa14431270', 2, 'Upgrade Apache Struts to 2.5.33', 'Replaces struts2-core and plugins, validates the struts.xml namespace configuration and redeploys the WAR. Revision 2: Add REST plugin removal.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_struts.yml", "extra_vars": {"struts_version": "2.5.33"}}'::jsonb, 'Struts 2.x web apps on Tomcat', 'HIGH', FALSE, 1800, 1, 'CHANGES_REQUESTED', '91259cc2-d441-571f-bd03-8a71433309f1', '2026-09-02 11:15:00+00'),
  ('12a38943-3564-564d-a896-222b68a8b1b2', 'b6bef499-7076-5513-87a4-05aa14431270', 3, 'Upgrade Apache Struts to 2.5.33', 'Replaces struts2-core and plugins, validates the struts.xml namespace configuration and redeploys the WAR. Revision 3: Remove REST plugin when unused.', 'ANSIBLE', '{"playbook": "playbooks/java/upgrade_struts.yml", "extra_vars": {"struts_version": "2.5.33", "remove_rest_plugin": true}}'::jsonb, 'Struts 2.x web apps on Tomcat', 'HIGH', FALSE, 1800, 1, 'REVIEW_PENDING', '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-09-09 11:15:00+00'),
  ('ca162a88-e49f-5da5-8682-bc17b250d3ea', 'd1371b91-8425-5ef6-b1c2-781c1a7f7ed0', 1, 'WAF virtual patch for Struts OGNL injection', 'Pushes an F5 ASM signature set that blocks OGNL expressions in Content-Type and namespace parameters.', 'HTTP', '{"method": "POST", "url": "https://lb-f5-01.corp.example.com/mgmt/tm/asm/signatures", "body": {"name": "struts-ognl-block", "mode": "blocking"}, "expect_status": 200}'::jsonb, 'Struts apps behind F5 ASM', 'LOW', FALSE, 1800, 0, 'APPROVED', '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-08 12:00:00+00'),
  ('abaea389-2b0f-519f-9b31-aa10b01dab5a', '5ef47b53-e74c-5696-84db-674c89a20d6c', 1, 'Upgrade OpenSSL via OS package manager', 'Applies the vendor security update for openssl/libssl using apt or dnf, then restarts services linked to libssl with needrestart.', 'ANSIBLE', '{"playbook": "playbooks/linux/package_security_update.yml", "extra_vars": {"packages": ["openssl", "libssl3"], "restart_dependent_services": true}}'::jsonb, 'Ubuntu 20.04/22.04, RHEL 8/9, Fedora', 'MEDIUM', FALSE, 1500, 1, 'APPROVED', '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-08 20:00:00+00'),
  ('6d91830d-b51d-54c2-a51a-0d3df4b7fdaa', 'd8099603-43d3-5be2-8c11-5a129c34ed2b', 1, 'Upgrade OpenSSH server to 9.8p1', 'Installs the vendor-backported OpenSSH build, validates sshd_config with sshd -t and reloads sshd without dropping sessions.', 'ANSIBLE', '{"playbook": "playbooks/linux/upgrade_openssh.yml", "extra_vars": {"target_version": "9.8p1", "validate_config": true}}'::jsonb, 'Linux servers', 'MEDIUM', FALSE, 1200, 1, 'APPROVED', '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-09 07:00:00+00'),
  ('7063248a-3803-5da2-8da9-66f49d7ce28c', 'd8099603-43d3-5be2-8c11-5a129c34ed2b', 2, 'Upgrade OpenSSH server to 9.8p1', 'Installs the vendor-backported OpenSSH build, validates sshd_config with sshd -t and reloads sshd without dropping sessions. Revision 2: Support Ubuntu 24.04 package names.', 'ANSIBLE', '{"playbook": "playbooks/linux/upgrade_openssh.yml", "extra_vars": {"target_version": "9.8p1", "validate_config": true, "supported_os": ["ubuntu-22.04", "ubuntu-24.04", "rhel-9"]}}'::jsonb, 'Linux servers', 'MEDIUM', FALSE, 1200, 1, 'REVIEW_PENDING', 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-10-14 11:15:00+00'),
  ('5d8b090a-f9b0-5b1c-8f3d-861fc6b344c7', '8f160588-2012-5ea0-a69a-3d553c0000f2', 1, 'Harden SSH ciphers (Terrapin mitigation)', 'Disables chacha20-poly1305 and *-etm MACs in sshd_config and ssh_config until both ends support strict key exchange.', 'ANSIBLE', '{"playbook": "playbooks/linux/ssh_cipher_hardening.yml", "extra_vars": {"disable_chacha": true, "disable_etm_macs": true}}'::jsonb, 'OpenSSH 9.5 and earlier', 'LOW', FALSE, 600, 0, 'APPROVED', '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-09 21:00:00+00'),
  ('5c933d94-78c6-5dc9-8dd0-3204b8c47b3f', '74b6095d-833b-5233-b1b6-048ebc2a7ea7', 1, 'Patch sudo to 1.9.5p2 or later', 'Upgrades the sudo package and verifies the version string and /etc/sudoers syntax with visudo -c.', 'AWS_SSM', '{"document": "AWS-RunShellScript", "parameters": {"commands": ["yum -y update sudo || apt-get -y install --only-upgrade sudo", "visudo -c"]}}'::jsonb, 'Linux servers', 'LOW', FALSE, 600, 0, 'APPROVED', '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-10 05:00:00+00'),
  ('ee1c4b14-43ea-5eae-9e2c-4e3a2fbcbbdb', '7f4d5dc4-37c9-524e-b9a6-dc936a3e8dc2', 1, 'Apply OS security errata (polkit, glibc, bash)', 'Installs security-classified updates only (yum --security / unattended-upgrade) and records the advisories applied.', 'AWS_SSM', '{"document": "AWS-RunPatchBaseline", "parameters": {"Operation": ["Install"], "RebootOption": ["NoReboot"]}}'::jsonb, 'Amazon Linux, RHEL, Ubuntu', 'MEDIUM', FALSE, 2400, 1, 'APPROVED', 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-10 17:00:00+00'),
  ('425a21cf-e295-5d82-873b-566012f11fc5', '0cac83b3-ffef-5c22-9c92-cbaa631a2a68', 1, 'Kernel security update with staged reboot', 'Installs the latest kernel from the vendor repo, sets it as default in GRUB and schedules a reboot in the next maintenance window.', 'ANSIBLE', '{"playbook": "playbooks/linux/kernel_update.yml", "extra_vars": {"reboot": false, "keep_previous_kernels": 2}}'::jsonb, 'RHEL 8/9, Ubuntu LTS', 'HIGH', FALSE, 2400, 1, 'APPROVED', 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-11 07:00:00+00');
INSERT INTO solution_versions (id, solution_id, version_no, title, description, executor, job_spec, applies_to, risk_level, requires_reboot, timeout_seconds, max_retries, status, created_by, created_at) VALUES
  ('8413df96-d3ba-5783-9b28-82f6bc6fbb69', '0cac83b3-ffef-5c22-9c92-cbaa631a2a68', 2, 'Kernel security update with staged reboot', 'Installs the latest kernel from the vendor repo, sets it as default in GRUB and schedules a reboot in the next maintenance window. Revision 2: Add livepatch where supported.', 'ANSIBLE', '{"playbook": "playbooks/linux/kernel_update.yml", "extra_vars": {"reboot": false, "keep_previous_kernels": 2, "use_livepatch": true}}'::jsonb, 'RHEL 8/9, Ubuntu LTS', 'HIGH', FALSE, 2400, 1, 'APPROVED', '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-09-04 11:15:00+00'),
  ('4abdce71-e6b6-52e2-86d6-6d99cc86af58', '0cac83b3-ffef-5c22-9c92-cbaa631a2a68', 3, 'Kernel security update with staged reboot', 'Installs the latest kernel from the vendor repo, sets it as default in GRUB and schedules a reboot in the next maintenance window. Revision 3: Auto reboot for non-prod.', 'ANSIBLE', '{"playbook": "playbooks/linux/kernel_update.yml", "extra_vars": {"reboot": false, "keep_previous_kernels": 2, "use_livepatch": true}}'::jsonb, 'RHEL 8/9, Ubuntu LTS', 'HIGH', FALSE, 2400, 1, 'CHANGES_REQUESTED', 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-10-06 11:15:00+00'),
  ('d5c02615-5605-5481-adce-15cf3e3ffb54', '2099971c-cd36-5b70-962a-7ed106d56893', 1, 'Upgrade curl and libcurl to 8.4.0 or later', 'Updates curl/libcurl packages and checks the SOCKS5 hostname handling regression test.', 'SHELL', '{"command": "yum -y update curl libcurl || apt-get -y install --only-upgrade curl libcurl4", "shell": "bash", "become": true}'::jsonb, 'Linux servers', 'LOW', FALSE, 600, 0, 'APPROVED', '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-11 16:00:00+00'),
  ('e530d5cb-a1b1-52e1-840f-e3a752fd23e7', '2099971c-cd36-5b70-962a-7ed106d56893', 2, 'Upgrade curl and libcurl to 8.4.0 or later', 'Updates curl/libcurl packages and checks the SOCKS5 hostname handling regression test. Revision 2: Verify package signature.', 'SHELL', '{"command": "rpm -K $(rpm -q curl) ; yum -y update curl libcurl || apt-get -y install --only-upgrade curl libcurl4", "shell": "bash", "become": true}'::jsonb, 'Linux servers', 'LOW', FALSE, 600, 0, 'APPROVED', 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-08-25 11:15:00+00'),
  ('ea270596-7401-52ca-a6d1-2ade6b46ee4c', '1c24cc73-5459-5c3e-bb03-c04e237a88a2', 1, 'Downgrade xz-utils to 5.4.6', 'Removes the affected xz 5.6.0/5.6.1 packages, installs 5.4.6 and restarts sshd.', 'SHELL', '{"command": "dnf -y downgrade xz xz-libs xz-devel && systemctl restart sshd", "shell": "bash", "become": true}'::jsonb, 'Fedora 40, Debian testing', 'MEDIUM', FALSE, 600, 0, 'APPROVED', 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-12 05:00:00+00'),
  ('dd1c722d-257c-51c0-89ad-4a7796d88adb', 'bb2db354-5b56-53f0-a6a4-8ed6b58870ff', 1, 'nginx HTTP/2 rapid reset mitigation', 'Sets keepalive_requests 1000 and http2_max_concurrent_streams 128, validates with nginx -t and reloads.', 'ANSIBLE', '{"playbook": "playbooks/web/nginx_http2_limits.yml", "extra_vars": {"keepalive_requests": 1000, "http2_max_concurrent_streams": 128}}'::jsonb, 'nginx 1.18+', 'LOW', FALSE, 600, 0, 'APPROVED', '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-12 13:00:00+00'),
  ('fe80f38c-1b03-5a34-8a1f-4ce78d389872', 'e785d04c-afc0-524e-9d4a-0b09d84c20b7', 1, 'Upgrade nginx to 1.25.3', 'Installs nginx from the official repository, performs a binary upgrade (USR2) without dropping connections.', 'ANSIBLE', '{"playbook": "playbooks/web/nginx_upgrade.yml", "extra_vars": {"nginx_version": "1.25.3", "zero_downtime": true}}'::jsonb, 'nginx on Linux', 'MEDIUM', FALSE, 900, 1, 'APPROVED', 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-13 03:00:00+00'),
  ('5e69f044-47d3-53d0-aac2-8458c08187a1', 'e785d04c-afc0-524e-9d4a-0b09d84c20b7', 2, 'Upgrade nginx to 1.25.3', 'Installs nginx from the official repository, performs a binary upgrade (USR2) without dropping connections. Revision 2: Pin to 1.26.x stable.', 'ANSIBLE', '{"playbook": "playbooks/web/nginx_upgrade.yml", "extra_vars": {"nginx_version": "1.26.1", "zero_downtime": true}}'::jsonb, 'nginx on Linux', 'MEDIUM', FALSE, 900, 1, 'APPROVED', 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-09-18 11:15:00+00'),
  ('3775602c-4c9a-527b-8400-94eb505fa6b5', 'f46d1d57-b402-5088-a80a-cbc8db7de1c4', 1, 'Upgrade Apache HTTP Server to 2.4.58', 'Upgrades httpd, removes legacy ''Require all granted'' on / and restarts the service gracefully.', 'ANSIBLE', '{"playbook": "playbooks/web/httpd_upgrade.yml", "extra_vars": {"httpd_version": "2.4.58", "graceful": true}}'::jsonb, 'Apache httpd 2.4.x', 'MEDIUM', FALSE, 900, 1, 'APPROVED', '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-13 10:00:00+00'),
  ('2d2447c4-9b9d-518c-b725-1862a93842fa', '0ebab7f6-ba6d-55fa-a92d-4b6a18f6983f', 1, 'Upgrade PHP to 8.2.20', 'Upgrades PHP and PHP-FPM, disables the CGI SAPI where not required.', 'ANSIBLE', '{"playbook": "playbooks/web/php_upgrade.yml", "extra_vars": {"php_version": "8.2.20", "disable_cgi": true}}'::jsonb, 'PHP 8.x', 'MEDIUM', FALSE, 900, 0, 'APPROVED', 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-13 21:00:00+00'),
  ('95f74e2d-0bce-5414-8926-a2707a9bcaf9', 'a2b46581-9f8c-52e4-a84e-60bfb0510af3', 1, 'Disable SMBv1 and apply MS17-010', 'Removes the SMB1Protocol feature, installs KB4012212/KB4012215 where missing and reports SMB signing state.', 'ANSIBLE', '{"playbook": "playbooks/windows/disable_smbv1.yml", "connection": "winrm", "extra_vars": {"kb": ["KB4012212", "KB4012215"]}}'::jsonb, 'Windows Server 2008 R2 - 2019', 'MEDIUM', TRUE, 1800, 1, 'APPROVED', '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-14 10:00:00+00'),
  ('5766176e-03eb-5b31-a72c-aecae3f53be4', '344b3f08-5e67-5d68-8edd-56190224636e', 1, 'Netlogon secure channel enforcement (Zerologon)', 'Installs the August 2020 cumulative update and sets FullSecureChannelProtection=1 on domain controllers.', 'ANSIBLE', '{"playbook": "playbooks/windows/zerologon_enforce.yml", "connection": "winrm", "extra_vars": {"enforcement": 1}}'::jsonb, 'Domain controllers', 'HIGH', TRUE, 2400, 0, 'APPROVED', '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-14 20:00:00+00'),
  ('a1192c6d-7f14-5f2f-a9a1-549528374028', '2092e870-9251-5b27-941e-a2e949a5b1ba', 1, 'Disable Print Spooler on non-print servers', 'Stops and disables the Spooler service on domain controllers and file servers, and installs the July 2021 out-of-band update.', 'ANSIBLE', '{"playbook": "playbooks/windows/disable_spooler.yml", "connection": "winrm"}'::jsonb, 'Windows Server 2012 R2 - 2022', 'LOW', FALSE, 900, 0, 'APPROVED', 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-15 07:00:00+00'),
  ('61216d0e-64a3-5849-a03e-3aec60ec9833', '56c2e81c-f53b-54eb-87bc-ff5cba6a2ace', 1, 'Enable NLA and install BlueKeep patch', 'Requires Network Level Authentication and installs KB4499175 for Server 2008 R2.', 'ANSIBLE', '{"playbook": "playbooks/windows/rdp_nla_bluekeep.yml", "connection": "winrm", "extra_vars": {"kb": "KB4499175"}}'::jsonb, 'Windows Server 2008 R2', 'MEDIUM', TRUE, 1800, 0, 'APPROVED', 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-15 21:00:00+00'),
  ('9ab02f39-3564-5951-9bc5-1cc5133e3b21', 'e0e3c825-c4eb-54fa-b0bd-73c624937729', 1, 'Install Exchange Server Security Update', 'Puts the DAG member in maintenance mode, installs the cumulative security update, runs health checks and exits maintenance mode.', 'ANSIBLE', '{"playbook": "playbooks/windows/exchange_security_update.yml", "connection": "winrm", "extra_vars": {"maintenance_mode": true}}'::jsonb, 'Exchange 2016/2019', 'HIGH', TRUE, 5400, 0, 'APPROVED', '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-16 04:00:00+00'),
  ('2dae7c3e-9e67-58a0-b0dc-39f164cabec6', 'e0e3c825-c4eb-54fa-b0bd-73c624937729', 2, 'Install Exchange Server Security Update', 'Puts the DAG member in maintenance mode, installs the cumulative security update, runs health checks and exits maintenance mode. Revision 2: Run ExchangeHealthChecker before and after.', 'ANSIBLE', '{"playbook": "playbooks/windows/exchange_security_update.yml", "connection": "winrm", "extra_vars": {"maintenance_mode": true, "run_health_checker": true}}'::jsonb, 'Exchange 2016/2019', 'HIGH', TRUE, 5400, 0, 'APPROVED', 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-09-21 11:15:00+00'),
  ('55530805-bcef-5be9-9961-3194403c2137', 'e688b2e4-f2ad-5b7e-a885-be31b64e1f3c', 1, 'Windows cumulative update via WSUS', 'Approves and installs the latest cumulative update for the target group and reports pending reboot state.', 'ANSIBLE', '{"playbook": "playbooks/windows/wsus_cumulative_update.yml", "connection": "winrm", "extra_vars": {"category": ["SecurityUpdates", "CriticalUpdates"]}}'::jsonb, 'Windows Server 2016 - 2022', 'MEDIUM', TRUE, 3600, 1, 'APPROVED', 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-16 15:00:00+00'),
  ('8542137e-eb87-5d15-947a-5e01550d9749', 'e688b2e4-f2ad-5b7e-a885-be31b64e1f3c', 2, 'Windows cumulative update via WSUS', 'Approves and installs the latest cumulative update for the target group and reports pending reboot state. Revision 2: Skip preview updates.', 'ANSIBLE', '{"playbook": "playbooks/windows/wsus_cumulative_update.yml", "connection": "winrm", "extra_vars": {"category": ["SecurityUpdates"], "skip_preview": true}}'::jsonb, 'Windows Server 2016 - 2022', 'MEDIUM', TRUE, 3600, 1, 'REVIEW_PENDING', '91259cc2-d441-571f-bd03-8a71433309f1', '2026-10-17 11:15:00+00'),
  ('500ac8ac-f69d-5ecb-8865-a0c66d63c889', '6c865fb9-1c0f-5cfb-8e6c-f39c71b27015', 1, 'Upgrade FortiOS to 7.2.8 via FortiManager', 'Stages the firmware on FortiManager and triggers a rolling HA upgrade with automatic config backup.', 'HTTP', '{"method": "POST", "url": "https://fortimanager.corp.example.com/jsonrpc", "body": {"method": "exec", "params": [{"url": "/um/firmware/upgrade", "data": {"version": "7.2.8"}}]}, "poll": true, "expect_status": 200}'::jsonb, 'FortiGate 100F/200F', 'HIGH', TRUE, 3600, 0, 'APPROVED', '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-17 03:00:00+00'),
  ('5b228718-7a47-52ad-95a4-c32d03275abb', '6c865fb9-1c0f-5cfb-8e6c-f39c71b27015', 2, 'Upgrade FortiOS to 7.2.8 via FortiManager', 'Stages the firmware on FortiManager and triggers a rolling HA upgrade with automatic config backup. Revision 2: Upgrade to 7.2.9 (CVE-2024-21762 fixed).', 'HTTP', '{"method": "POST", "url": "https://fortimanager.corp.example.com/jsonrpc", "body": {"method": "exec", "params": [{"url": "/um/firmware/upgrade", "data": {"version": "7.2.9"}}]}, "poll": true, "expect_status": 200}'::jsonb, 'FortiGate 100F/200F', 'HIGH', TRUE, 3600, 0, 'APPROVED', 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-09-10 11:15:00+00'),
  ('46724ab9-2905-58a2-af77-9b93a117ef75', '6c865fb9-1c0f-5cfb-8e6c-f39c71b27015', 3, 'Upgrade FortiOS to 7.2.8 via FortiManager', 'Stages the firmware on FortiManager and triggers a rolling HA upgrade with automatic config backup. Revision 3: Add pre-upgrade config diff.', 'HTTP', '{"method": "POST", "url": "https://fortimanager.corp.example.com/jsonrpc", "body": {"method": "exec", "params": [{"url": "/um/firmware/upgrade", "data": {"version": "7.2.9"}}]}, "poll": true, "expect_status": 200}'::jsonb, 'FortiGate 100F/200F', 'HIGH', TRUE, 3600, 0, 'REVIEW_PENDING', 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-10-19 11:15:00+00'),
  ('6a234589-339d-5f43-9288-b77f49ef443b', '4c8f4d47-0adf-59d2-9885-3cbe8a5af4a2', 1, 'Upgrade BIG-IP to 15.1.10.2 via iControl', 'Installs the target software volume, copies the configuration and activates it on the standby unit first.', 'HTTP', '{"method": "POST", "url": "https://{{hostname}}/mgmt/tm/sys/software/image", "body": {"command": "install", "name": "BIGIP-15.1.10.2-0.0.2.iso", "volume": "HD1.2"}, "poll": true}'::jsonb, 'BIG-IP 15.x', 'HIGH', TRUE, 3600, 0, 'APPROVED', '016ec7f7-89c8-546d-8e04-f08a7f383784', '2026-06-17 16:00:00+00'),
  ('2006faf4-50ae-54e0-be93-694a137c619a', '988e2957-d738-5957-aff3-079d01e68522', 1, 'Upgrade NetScaler ADC to 13.1-49.15', 'Uploads the build, runs the pre-upgrade validation and performs a staged HA failover upgrade.', 'HTTP', '{"method": "POST", "url": "https://{{hostname}}/nitro/v1/config/systemfile", "body": {"filename": "build-13.1-49.15_nc_64.tgz"}, "poll": true}'::jsonb, 'NetScaler MPX/SDX', 'HIGH', TRUE, 3600, 0, 'APPROVED', '21909828-61d4-5921-bcaa-2f11151dab91', '2026-06-18 04:00:00+00'),
  ('d3c7eb21-120d-5663-b8a7-0bdae321902f', 'cfc5bcbd-d37b-5efd-9366-cc0dd3770839', 1, 'Apply PAN-OS 10.2.9-h1 hotfix', 'Downloads and installs the hotfix on the passive HA peer, fails over, then upgrades the former active unit.', 'HTTP', '{"method": "GET", "url": "https://{{hostname}}/api/?type=op&cmd=<request><system><software><install><version>10.2.9-h1</version></install></software></system></request>", "poll": true}'::jsonb, 'PAN-OS 10.x', 'HIGH', TRUE, 3600, 0, 'APPROVED', '9c64102b-fa56-54ee-8f9d-7f4f025d70fb', '2026-06-18 11:00:00+00'),
  ('2ff15630-a69a-51f7-b7f3-c4a23e8d6635', 'e973a712-9fb1-5704-850b-8a45ab94b7a8', 1, 'Upgrade IOS XE and disable HTTP server', 'Installs the fixed IOS XE image in install mode and applies ''no ip http server / no ip http secure-server''.', 'ANSIBLE', '{"playbook": "playbooks/network/iosxe_upgrade.yml", "connection": "network_cli", "extra_vars": {"image": "cat9k_iosxe.17.9.4a.SPA.bin", "disable_http_server": true}}'::jsonb, 'Catalyst 9000', 'HIGH', TRUE, 3600, 0, 'APPROVED', '7fd287af-f671-585b-b616-2077bbab4cee', '2026-06-18 23:00:00+00');
INSERT INTO solution_versions (id, solution_id, version_no, title, description, executor, job_spec, applies_to, risk_level, requires_reboot, timeout_seconds, max_retries, status, created_by, created_at) VALUES
  ('d310a5fc-bdf3-59fb-b3bb-b8aaa465986b', '7546bcba-3e87-5936-ad0e-20023ada3214', 1, 'Upgrade Jenkins to 2.442 LTS', 'Replaces jenkins.war, backs up JENKINS_HOME and restarts after quiescing running builds.', 'ANSIBLE', '{"playbook": "playbooks/devops/jenkins_upgrade.yml", "extra_vars": {"jenkins_version": "2.426.3", "backup_home": true}}'::jsonb, 'Jenkins LTS', 'MEDIUM', FALSE, 1800, 1, 'APPROVED', 'aa3b93f1-cb17-5718-af25-db1f497e3adc', '2026-06-19 11:00:00+00'),
  ('b888964b-9b2c-5394-b243-11f1f4f777e7', '681b691a-785c-5d11-89dd-fa8490913642', 1, 'Upgrade GitLab to 13.10.3', 'Runs the omnibus upgrade path with background migrations check, then verifies repository integrity.', 'SHELL', '{"command": "gitlab-ctl pg-upgrade -V 13 || true; apt-get -y install gitlab-ce=13.10.3-ce.0 && gitlab-ctl reconfigure", "shell": "bash", "become": true}'::jsonb, 'GitLab omnibus', 'HIGH', FALSE, 3600, 0, 'APPROVED', 'b92c8a6b-ed01-5e43-9c67-58b0d8d62a5a', '2026-06-20 00:00:00+00'),
  ('19a511f5-7aed-570d-87b3-92008117e7fa', '8a93a5dc-9817-5a66-9bb8-d4a8ad46b75a', 1, 'Upgrade TeamCity to 2023.05.4', 'Applies the TeamCity patch plugin and restarts the server; fallback is the full distribution upgrade.', 'ANSIBLE', '{"playbook": "playbooks/devops/teamcity_upgrade.yml", "extra_vars": {"version": "2023.05.4"}}'::jsonb, 'TeamCity 2023.05.x', 'MEDIUM', FALSE, 1800, 0, 'APPROVED', '91259cc2-d441-571f-bd03-8a71433309f1', '2026-06-20 09:00:00+00'),
  ('47add05d-1b55-58d9-a557-a10decb6036f', '006953f7-2bc4-57ba-8cac-76f2cdd2fe8f', 1, 'Upgrade Confluence Data Center to 8.5.3', 'Rolling node upgrade using zero-downtime mode; the setup endpoints are blocked at the reverse proxy first.', 'ANSIBLE', '{"playbook": "playbooks/collab/confluence_upgrade.yml", "extra_vars": {"version": "8.5.3", "zero_downtime": true}}'::jsonb, 'Confluence DC', 'HIGH', FALSE, 3600, 0, 'APPROVED', 'bf4a73e9-232f-5ce9-916a-3251bcbd17e8', '2026-06-20 22:00:00+00'),
  ('000d8d76-977d-5d7d-b77b-a687ca7e938b', '5d99d139-7d01-5bba-a91a-4b8ea1df50cf', 1, 'Apply MOVEit Transfer security patch', 'Disables HTTP/HTTPS traffic, installs the vendor patch, validates files and re-enables traffic.', 'ANSIBLE', '{"playbook": "playbooks/windows/moveit_patch.yml", "connection": "winrm", "extra_vars": {"patch": "MOVEit2022.1.6"}}'::jsonb, 'MOVEit Transfer 2021+', 'HIGH', TRUE, 3600, 0, 'APPROVED', '842a5182-43e1-5005-bb88-1e2ba9741f62', '2026-06-21 05:00:00+00'),
  ('b1bbac5b-2952-5691-9a5d-3554d0d41327', '0b09a43c-8065-58d5-90a6-000875bbf745', 1, 'Barracuda ESG security patch (BNSF-36456)', 'Triggers the Barracuda central update service to download and apply the security patch and reboot.', 'HTTP', '{"method": "POST", "url": "https://{{hostname}}/cgi-mod/index.cgi", "body": {"action": "update", "patch": "BNSF-36456"}, "poll": true}'::jsonb, 'Barracuda ESG 5.x-9.x', 'MEDIUM', TRUE, 1800, 0, 'APPROVED', 'a0f3f073-4598-57b7-a4e7-5c167a07da9f', '2026-06-21 17:00:00+00'),
  ('c3583927-6647-5ae8-8f53-07e55caefa34', 'ebf5f50f-ee3b-5f07-86d9-1a033284d120', 1, 'Upgrade Pulse Connect Secure to 9.1R18', 'Uploads the package via the admin API and installs it with automatic rollback if the health probe fails.', 'HTTP', '{"method": "POST", "url": "https://{{hostname}}/api/v1/system/maintenance/install", "body": {"package": "ps-pcs-9.1R18.pkg"}, "poll": true}'::jsonb, 'Pulse Connect Secure 9.x', 'HIGH', TRUE, 3600, 0, 'APPROVED', '63edf6e4-d231-584f-b6a9-ac5920b1ddd6', '2026-06-22 06:00:00+00'),
  ('32489678-72df-5e62-925f-2ecff37eaf80', '28441d9e-7f54-5777-86d9-02e266e1afe7', 1, 'Rebuild Node images with libwebp 1.3.2 (sharp 0.32.6)', 'Bumps sharp to 0.32.6 in the lockfile, rebuilds the container image and rolls it out through the CD pipeline.', 'SHELL', '{"command": "npm install sharp@0.32.6 --save-exact && npm audit --omit=dev && ./ci/build_and_deploy.sh", "shell": "bash"}'::jsonb, 'Node.js services using sharp or electron', 'MEDIUM', FALSE, 1800, 0, 'APPROVED', 'fd72b00c-eb25-5584-99e6-0a8f4d118eb4', '2026-06-22 14:00:00+00'),
  ('68d63fe4-c527-5da9-b86c-e13865ec9ce3', '4871a3d3-7744-5518-b82c-abc2f7feff8d', 1, 'Disable TLS 1.0/1.1 on load balancers', 'Removes legacy TLS protocol versions from all client-ssl profiles on BIG-IP.', 'HTTP', '{"method": "PATCH", "url": "https://lb-f5-01.corp.example.com/mgmt/tm/ltm/profile/client-ssl/~Common~clientssl", "body": {"options": ["no-tlsv1", "no-tlsv1.1"]}, "expect_status": 200}'::jsonb, 'BIG-IP client-ssl profiles', 'MEDIUM', FALSE, 600, 0, 'APPROVED', '1d1369fa-24ee-52ee-b08e-2de35ec975bb', '2026-06-23 02:00:00+00'),
  ('de8069e5-0890-5d40-ad9a-c4c464f4ef2a', '4871a3d3-7744-5518-b82c-abc2f7feff8d', 2, 'Disable TLS 1.0/1.1 on load balancers', 'Removes legacy TLS protocol versions from all client-ssl profiles on BIG-IP. Revision 2: Phase 2 - include internal virtual servers.', 'HTTP', '{"method": "PATCH", "url": "https://lb-f5-01.corp.example.com/mgmt/tm/ltm/profile/client-ssl/~Common~clientssl", "body": {"options": ["no-tlsv1", "no-tlsv1.1"]}, "expect_status": 200}'::jsonb, 'BIG-IP client-ssl profiles', 'MEDIUM', FALSE, 600, 0, 'REJECTED', '21909828-61d4-5921-bcaa-2f11151dab91', '2026-08-30 11:15:00+00'),
  ('79970686-cf47-5aac-89a1-8a3bf35b7fea', '47c8c805-24a3-5a8d-a56f-14273e0c1c08', 1, 'CIS baseline: SSH configuration hardening', 'Applies CIS Level 1 sshd_config settings: PermitRootLogin no, MaxAuthTries 4, ClientAliveInterval 300.', 'ANSIBLE', '{"playbook": "playbooks/linux/cis_ssh_baseline.yml", "extra_vars": {"profile": "level1"}}'::jsonb, 'Linux servers', 'LOW', FALSE, 900, 0, 'APPROVED', '9fb3c1fd-15f4-5d14-a6ab-48d69c10b369', '2026-06-23 15:00:00+00'),
  ('5d62e246-6716-5a53-95b7-2c025501c6a9', '8aba28f0-5f16-5413-a2d6-d350027651b7', 1, 'Rotate service account credentials in Vault', 'Rotates database and API service account secrets in HashiCorp Vault and restarts consumers with the new lease.', 'SHELL', '{"command": "vault write -f database/rotate-root/{{db}} && ./scripts/restart_consumers.sh {{db}}", "shell": "bash"}'::jsonb, 'Vault-managed secrets', 'HIGH', FALSE, 900, 0, 'APPROVED', 'b78d350b-e820-5a73-a188-84cec4af0086', '2026-06-23 23:00:00+00'),
  ('8c44c972-38af-509c-a2f5-2eda45bed1aa', '637c07c7-e6ca-524d-ab21-7461b39ef63f', 1, 'Rebuild container base images with patched OpenSSL', 'Triggers the CI pipeline to rebuild all base images from the latest patched distro layers and opens deployment PRs.', 'HTTP', '{"method": "POST", "url": "https://jenkins-prod-01.corp.example.com/job/base-images/buildWithParameters", "params": {"REBUILD_ALL": "true"}, "expect_status": 201}'::jsonb, 'Container base images', 'MEDIUM', FALSE, 3600, 0, 'REVIEW_PENDING', 'f75d184f-0e4e-5cb4-aa2b-10b35d349376', '2026-06-24 12:00:00+00'),
  ('a9eae8d4-226e-5ef3-9811-798587b02b1b', '7faa0ef5-5069-59a2-9915-a537bea73564', 1, 'Rotate expiring TLS certificates in ACM', 'Requests renewed certificates in AWS Certificate Manager and updates the load balancer listeners.', 'AWS_SSM', '{"document": "AWS-ConfigureAWSPackage", "parameters": {"action": ["Install"], "name": ["acm-renew"]}}'::jsonb, 'ALB/NLB listeners', 'MEDIUM', FALSE, 900, 0, 'CHANGES_REQUESTED', '7d5a0560-1d9a-5d89-961a-a8f359761a63', '2026-06-24 22:00:00+00'),
  ('fa25ec8d-a8bc-537a-8f64-381134689f3a', '312e5cc9-f0cc-586f-9907-bf83d49f2c04', 1, 'Deploy Windows LAPS to member servers', 'Installs and configures Windows LAPS so local administrator passwords are unique and rotated every 30 days.', 'ANSIBLE', '{"playbook": "playbooks/windows/laps_rollout.yml", "connection": "winrm", "extra_vars": {"rotation_days": 30}}'::jsonb, 'Windows Server 2019+', 'MEDIUM', FALSE, 1200, 0, 'REVIEW_PENDING', 'eedda94d-d0b5-5bf8-8a30-c5a7a6b988a5', '2026-06-25 11:00:00+00'),
  ('ff8d6822-93b8-51d5-8b26-06edc58b9670', 'd256e48b-e6b3-5cea-8de5-698fb8a2206d', 1, 'Block Confluence setup endpoints at reverse proxy (interim)', 'Adds a deny rule for /setup/* paths on the nginx reverse proxy in front of Confluence until the upgrade is done.', 'ANSIBLE', '{"playbook": "playbooks/web/nginx_deny_path.yml", "extra_vars": {"paths": ["/setup/", "/server-info.action"]}}'::jsonb, 'Confluence behind nginx', 'LOW', FALSE, 300, 0, 'REJECTED', '03a6bb56-3b87-5791-b5f7-15712ae3c2b1', '2026-06-25 21:00:00+00');
